def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # Colored cells along the perpendicular arm of the 5 guide define row/column fills.
    hbars=[r for r in range(h) if sum(v==5 for v in g[r])>=2]
    vbars=[c for c in range(w) if sum(g[r][c]==5 for r in range(h))>=2]
    if hbars and (not vbars or len(hbars)>=len(vbars)):
        rbar=hbars[0]; cs=[c for c,v in enumerate(g[rbar]) if v==5]; lo,hi=min(cs),max(cs)
        # Use colored labels adjacent to the guide. When labels lie on its left,
        # fill each guide row from left to right; otherwise fill beneath it.
        left_labels=[r for r in range(h) if lo>0 and g[r][lo-1] not in (0,5)]
        if left_labels:
            for r in left_labels:
                color=g[r][lo-1]
                for c in range(lo,hi+1):
                    if g[r][c] in (0,5): g[r][c]=color
        else:
            for r in range(rbar+1,h):
                color=g[r][lo]
                if color in (0,5): continue
                for c in range(lo,hi+1): g[r][c]=color
    elif vbars:
        cbar=vbars[0]; rs=[r for r in range(h) if g[r][cbar]==5]; lo,hi=min(rs),max(rs)
        # Horizontal label rows at the foot of guide define alternating row templates.
        seedrows=[r for r in range(h) if any(g[r][c] not in (0,5) for c in range(cbar+1,w))]
        if seedrows:
            for r in seedrows:
                a=cbar+1
                while a<w and g[r][a] in (0,5): a+=1
                pattern=g[r][a:]
                # Copy the explicit template onto every row of the guide length.
                for rr in range(lo,hi+1):
                    if rr==r: continue
                    for j,val in enumerate(pattern):
                        if a+j<w: g[rr][a+j]=val
    return g

