def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # A 5 guide across a row: extend the label beneath its leftmost cell
    # through the horizontal span.
    horizontal=[r for r in range(h) if sum(v==5 for v in g[r])>=2]
    vertical=[c for c in range(w) if sum(g[r][c]==5 for r in range(h))>=2]
    if horizontal:
        rbar=horizontal[0]
        cols=[c for c,v in enumerate(g[rbar]) if v==5]
        # separate contiguous guide segments (gap between independent bars)
        spans=[]
        for c in cols:
            if not spans or c>spans[-1][-1]+1: spans.append([c])
            else: spans[-1].append(c)
        for span in spans:
            lo,hi=span[0],span[-1]
            for r in range(rbar+1,h):
                label=g[r][lo]
                if label not in (0,5):
                    for c in range(lo+1,hi+1):
                        if g[r][c]==0: g[r][c]=label
    if vertical:
        cbar=max(vertical)
        rows=[r for r in range(h) if g[r][cbar]==5]
        top,bottom=min(rows),max(rows)
        seedrows=[r for r in range(bottom+1,h) if any(g[r][c] not in (0,5) for c in range(cbar+1,w))]
        if seedrows:
            first=seedrows[0]
            templates=[g[r][cbar+1:w] for r in seedrows]
            for r in range(top,bottom+1):
                template=templates[(r-first)%len(templates)]
                for k,val in enumerate(template,cbar+1):
                    if k<w and g[r][k]==0: g[r][k]=val
    return g
