def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # Repeat the two-row color pattern at the bottom of the vertical 5 guide
    # upwards over its full length, then fill the left area by adjacent labels.
    vcols=[c for c in range(w) if sum(g[r][c]==5 for r in range(h))>=2]
    hrows=[r for r in range(h) if sum(v==5 for v in g[r])>=2]
    if vcols:
        c=max(vcols)
        rows=[r for r in range(h) if g[r][c]==5]
        lo,hi=min(rows),max(rows)
        sample=[r for r in range(hi+1,h) if any(g[r][j] not in (0,5) for j in range(c+1,w))]
        # Continue the seed pattern upward from the bottom edge of the guide.
        if sample:
            templates=[g[r][c+1:w] for r in sample]
            for r in range(lo,hi+1):
                template=templates[(hi-r+1)%len(templates)]
                for j,val in enumerate(template,c+1):
                    if j<w and g[r][j]==0: g[r][j]=val
    if hrows:
        r=hrows[0]
        cols=[j for j,v in enumerate(g[r]) if v==5]
        if cols:
            right=max(cols)
            for i in range(r+1,h):
                label=g[i][0]
                if label not in (0,5):
                    for j in range(1,right):
                        if g[i][j]==0: g[i][j]=label
    return g

