def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # Find 5-valued straight guide lines.
    vcols=[c for c in range(w) if sum(g[r][c]==5 for r in range(h))>=2]
    hrows=[r for r in range(h) if sum(v==5 for v in g[r])>=2]
    # For a vertical guide, the adjacent color sequence at its base repeats upward.
    for c in vcols:
        spine=[r for r in range(h) if g[r][c]==5]
        top,bottom=min(spine),max(spine)
        # Seed rows are the non-5 horizontal color runs directly attached to guide.
        seeds=[r for r in range(h) if c+1<w and g[r][c+1] not in (0,5)]
        if seeds:
            templates=[]
            for r in seeds:
                end=c+1
                while end<w and g[r][end] not in (0,5): end+=1
                templates.append(g[r][c+1:end])
            for r in range(top,bottom+1):
                pat=templates[(r-seeds[0])%len(templates)]
                for j,val in enumerate(pat,c+1):
                    if j<w and g[r][j]==0: g[r][j]=val
    # For a horizontal guide, the seed values immediately below its first 5
    # cell are copied across the guide span on each corresponding row.
    for rbar in hrows:
        cols=[c for c,v in enumerate(g[rbar]) if v==5]
        spans=[]
        for c in cols:
            if not spans or c>spans[-1][-1]+1: spans.append([c])
            else: spans[-1].append(c)
        for span in spans:
            lo,hi=span[0],span[-1]
            for r in range(rbar+1,h):
                val=g[r][lo]
                if val not in (0,5):
                    for c in range(lo+1,hi+1):
                        if g[r][c]==0: g[r][c]=val
    return g
